        <section class="mistake-rationale" aria-labelledby="mistake-rationale-title"><h3 id="mistake-rationale-title">Saved explanation</h3><p><?= $escape($item['explanation'] ?? $question['explanation'] ?? 'No explanation was saved with this attempt.') ?></p></section>
