    <?php if ($references !== []): ?><section class="mistake-study-references card" aria-labelledby="mistake-study-title"><h2 id="mistake-study-title">Study and source references</h2><ul><?php foreach ($references as $reference): if (!is_array($reference)) continue; $url = is_scalar($reference['url'] ?? null) ? (string) $reference['url'] : ''; $title = is_scalar($reference['title'] ?? null) ? (string) $reference['title'] : 'Study reference'; $section = is_scalar($reference['section_heading'] ?? null) ? trim((string) $reference['section_heading']) : ''; if ($url === '') continue; $external = preg_match('#\Ahttps?://#i', $url) === 1; ?><li><?php if ($external): ?><a href="<?= $escape($url) ?>" target="_blank" rel="noopener noreferrer"><?= $escape($title) ?></a><?php else: ?><a href="<?= $escape($url) ?>"><?= $escape($section !== '' ? $section : $title) ?></a><?php endif; ?><?php if (!empty($reference['source_status'])): ?> · <?= $escape($reference['source_status']) ?><?php endif; ?><?php if (!empty($reference['academic_status'])): ?> · Academic status: <?= $escape($reference['academic_status']) ?><?php endif; ?></li><?php endforeach; ?></ul><p class="muted-note">A source or study association is not the same as an independently approved exact teaching link.</p></section><?php else: ?><section class="mistake-study-references card"><h2>Study next</h2><p>No BoardPrep study or source reference is currently linked to this question. You can return to your own notes, or choose related practice only if a precise taxonomy relationship is available.</p><p><a class="button button-outline" href="/my-notes?return_to=<?= rawurlencode($returnTo) ?>">Open My Notes</a></p></section><?php endif; ?>

