    </section>

    <?php if (!empty($detail['is_mistake'])): ?>
    <section class="mistake-recovery-actions card" aria-labelledby="mistake-actions-title"><p class="eyebrow">Choose your next step</p><h2 id="mistake-actions-title">Return to this question or practice its topic</h2><?php if ($q6403ScoringHold): ?><p>This historical CSE question remains under owner review and cannot be added to a retry pool. Related practice can use other eligible questions sharing a recorded topic or concept.</p><?php else: ?><p><strong>Retry Missed Questions</strong> selects only eligible questions you previously missed. <strong>Practice Related Topics</strong> selects other eligible questions sharing a recorded topic or concept.</p><?php endif; ?>
        <form method="post" action="/mistake-notebook/practice" class="mistake-practice-form"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken ?? '') ?>"><input type="hidden" name="board" value="<?= $escape($board) ?>"><input type="hidden" name="subject" value="<?= $escape($subject) ?>"><input type="hidden" name="topic" value="<?= $escape($topicId) ?>"><input type="hidden" name="focus_question_id" value="<?= $escape($questionId) ?>"><label for="review-level">Civil Service level</label><?php if ($isCse): ?><select id="review-level" name="civil_service_level" required><option value="">Choose level</option><?php foreach (['PROFESSIONAL','SUBPROFESSIONAL'] as $level): ?><option value="<?= $level ?>"<?= strtoupper((string) ($anchorAttempt['civil_service_level'] ?? '')) === $level ? ' selected' : '' ?>><?= $level === 'PROFESSIONAL' ? 'Professional' : 'Subprofessional' ?></option><?php endforeach; ?></select><?php else: ?><input type="hidden" name="civil_service_level" value=""><?php endif; ?><label for="review-count">Maximum session size</label><select id="review-count" name="count" required><?php foreach ([5,10,15,20] as $size): ?><option value="<?= $size ?>"><?= $size ?> questions</option><?php endforeach; ?></select><div class="page-actions<?= $q6403ScoringHold ? ' single-recovery-action' : '' ?>"><?php if (!$q6403ScoringHold): ?><button class="button button-green" name="practice_type" value="retry" type="submit">Retry Missed Questions</button><?php endif; ?><button class="button button-outline" name="practice_type" value="related" type="submit">Practice Related Topics</button></div></form>
